/* Browser-local Bot saves only. Never a wallet or multiplayer authority. */
(()=>{const key='bunny-bot-save-v1',ownerKey='bunny-bot-active-v1';
 const read=()=>{try{const raw=localStorage.getItem(key);if(!raw||raw.length>2000000)return null;const s=JSON.parse(raw);return s?.version===1&&Number.isFinite(s.savedAt)&&typeof s.playerId==='string'&&s.room?.phase==='playing'&&Array.isArray(s.room.players)&&s.room.players.length===4&&s.room.players.filter(p=>!p.isBot).length===1&&s.room.players.some(p=>p.id===s.playerId&&!p.isBot)&&typeof s.room.code==='string'&&s.room.match&&['east','south'].includes(s.room.match.roundWind)&&Number.isInteger(s.room.match.handNumber)&&s.room.rules&&Number.isFinite(s.room.rules.actionTimeoutMs)&&s.room.game?.hands&&['east','south','west','north'].every(seat=>Array.isArray(s.room.game.hands[seat])&&Number.isFinite(s.room.scores?.[seat]))?s:null}catch{return null}};
 window.BunnyBotSave={key,ownerKey,read,write(s){try{localStorage.setItem(key,JSON.stringify(s));return true}catch{return false}},archiveInvalid(){try{const raw=localStorage.getItem(key);if(raw)localStorage.setItem(key+'-backup',raw);localStorage.removeItem(key)}catch{}},summary(){const s=read();if(!s)return null;const m=s.room.handMatch??s.room.match,ms=s.room.rules?.actionTimeoutMs;const c=s.room.players.find(p=>p.id===s.playerId)?.character;return{character:['yellow','king','ninja','wizard'].includes(c)?c:'yellow',difficulty:ms===10000?'high':ms===20000?'medium':'low',round:m.roundWind==='south'?'south':'east',hand:Number.isInteger(m.handNumber)?m.handNumber:1,honba:Number.isInteger(m.honba)&&m.honba>=0?m.honba:0,finished:!!s.room.match.finished,savedAt:s.savedAt}},claim(id){try{localStorage.setItem(ownerKey,id);return true}catch{return false}},owns(id){try{return localStorage.getItem(ownerKey)===id}catch{return true}}};
})();
